export const DD_PURPOSE = "Partnership Due Diligence Workbook\nThe purpose of this tool is to work with partners to identify, analyze, and manage material risks to our ability to deliver safe, effective, and compliant programs together."

/** Scoping → "Due diligence preparation document review checklist" */
export const DD_CHECKLIST: { key: string; label: string }[] = [{"key":"doc_1","label":"Organizational organigram/org chart"},{"key":"doc_2","label":"Code of Conduct"},{"key":"doc_3","label":"Safeguarding Policy"},{"key":"doc_4","label":"Gender Equality, Diversity and Inclusion (GEDI) Policy"},{"key":"doc_5","label":"Grant Management Policy/Manual"},{"key":"doc_6","label":"Finance Manual/Finance Policy"},{"key":"doc_7","label":"Procurement Policy + Asset Management Policy"},{"key":"doc_8","label":"HR Policy / HR Manual"},{"key":"doc_9","label":"Subaward Management Policy/Manual"},{"key":"doc_10","label":"Certificate of Registration"},{"key":"doc_11","label":"Anti-Fraud, Anti-Corruption Policy"},{"key":"doc_12","label":"Conflict of Interest Policy"},{"key":"doc_13","label":"Security Policy"},{"key":"doc_14","label":"MEAL Policy"},{"key":"doc_15","label":"Audit Reports – Last Two Years"},{"key":"doc_16","label":"Board Meeting Minutes – Audit Discussions"},{"key":"doc_17","label":"Board of Directors / Board Members List"},{"key":"doc_18","label":"Full names + IDs of key individuals"},{"key":"doc_19","label":"Asset Management Policy"},{"key":"doc_20","label":"Data Protection / Data Privacy Policy"}]

/** Vetting → platforms checked for social media and internet presence */
export const DD_PLATFORMS: string[] = ["Facebook","Twitter","LinkedIn","TikTok","YouTube","Google"]
export const DD_SEARCH_INSTRUCTIONS = "Internet Search Instructions: Search the organization’s full name, alternative names/acronyms, and key personnel names, combined with relevant terms such as fraud, corruption, bribery, embezzlement, misconduct, allegations, investigation, lawsuit, sanctions, debarment, safeguarding, PSEA, abuse, harassment, aid diversion, conflict of interest, terrorism, terrorist financing, and financial irregularities."

/** Vetting → Vetting Analysis questions (answer Yes/No with basis, issues and risks) */
export const DD_VETTING_QUESTIONS: { key: string; topic: string; question: string }[] = [{"key":"vq_1","topic":"Legal","question":"Is the organization legally registered in the country it operates in?"},{"key":"vq_2","topic":"Political","question":"Does the organization or its senior staff have any relationship or affiliation with a political party, movement or high-profile individual?"},{"key":"vq_3","topic":"Armed Groups","question":"Does the organization or its senior staff have any relationship or affiliation with an armed group?"},{"key":"vq_4","topic":"Human Rights Violations","question":"Is there a credible allegation or evidence that the organization or its senior staff have committed gross violations of human rights?"},{"key":"vq_5","topic":"Values","question":"Does the organization have any values that may be inconsistent with the RHS’s values or the requirements of the proposed partnership?"},{"key":"vq_6","topic":"Exploitation/Abuse/Corruption/Criminal Conduct","question":"Does the organization or senior staff have any history of exploitation or abuse perpetrated against beneficiaries, or sexual violence perpetrated against staff or other aid workers, human trafficking, corruption, money laundering, or other criminal conduct?"},{"key":"vq_7","topic":"Poor performance","question":"Does the organization have a history of poor performance?"},{"key":"vq_8","topic":"Finance/Compliance Issues","question":"Has an external audit identified a material financial and/or compliance issue in the last three years?"},{"key":"vq_9","topic":"Reputational Harm to the RHS or donor","question":"Is there a material risk that the proposed partnership between the RHS and organization could cause reputational harm to the RHS or donor?"}]

export interface PcaItem { key: string; area: string; high: string; medium: string; emerging: string }
export interface PcaSection { key: PcaKey; title: string; materials: string; interview: string; items: PcaItem[] }
export type PcaKey = "safe" | "quality" | "meal" | "grants" | "finance" | "hr" | "supply" | "subaward"

/** Full Partner Capacity Analysis — eight scored sections (High = 3, Medium = 2, Emerging = 1, N/A = never applicable) */
export const PCA_SECTIONS: PcaSection[] = [{"key":"safe","title":"Safe programming","materials":"Materials to be requested and reviewed before the meeting: \n1. Code of Conduct\n2. Safeguarding policy\n3. GEDI policy","interview":"Please ask the following questions. As the partner answers, ask follow up questions as they arise through the natural flow of conversation. Use active listening skills to create a conversation about the content area.\n\n1. Is your organization familiar with the humanitarian principles? If so, could you please tell me how they're incorporated into your programming?\n\n2. Does your organization have a client safeguarding policy? If so, could you please tell me about it in the context of your work? Please provide an example of how it is utilized during implementation.\n\n3. Does your organization have a code of conduct? If yes, could you tell me about it and how employees are familiarized with it? How are violations handled?\n\n4. What is your organization's approach to gender equality, diversity and inclusion? Could you tell me an example of how gender equality, diversity, and inclusion is incorporated into your organization's practices?\n\n5. What is your organization's approach to ensuring staff health, safety, and psychosocial wellbeing? For example health insurance (as applicable), counseling services, and personal safety.\nNote that many countries where RHS operates have nationalized healthcare. Therefore, employee sponsored health insurance is irrelevant.\n\n6. What does your organization do to ensure staff safety and security? Or ask if they have context appropriate security management plan.\n\nAfter the meeting, please use the minutes to answer the questions below.","items":[{"key":"safe_1","area":"Humanitarian Principles","high":"The organization incorporates humanitarian principles into its programming (humanity, neurtality, impartiality and independence) OR, in the case of development organizations, they are incorporated without knowing that they abide by the principles.","medium":"Some of the principles are incorporated into the organizations work, either intentionally or unintentionally.","emerging":"The organization does not consider the humanitarian principles in programming."},{"key":"safe_2","area":"Safeguarding","high":"The organization has safeguarding policies and procedures in place to prevent discrimination, sexual harassment and sexual abuse and exploitation of clients by anyone employed by or affiliated with the organization complete with confidential reporting.","medium":"The organization has a safeguarding policy, but it has gaps in mitigating or preventing the risk of abuse to clients.","emerging":"There is no safeguarding policy."},{"key":"safe_3","area":"Safeguarding","high":"Staff, interns, and volunteers are trained in safeguarding policies. In-person or self-led trainings and workshops occur at regular intervals for staff. Staff who interact with beneficiaries are required to attend a safeguarding training.","medium":"Staff are provided with the safeguarding policy upon hiring and sign that they have read it, but there are no required trainings for staff who interface with clients.","emerging":"The safeguarding policy exists, but client facing staff aren't provided with it OR it does not exist."},{"key":"safe_4","area":"Safeguarding","high":"There is an easily accessible confidential reporting system for safeguarding violations.","medium":"Not applicable","emerging":"There is not confidential reporting system."},{"key":"safe_5","area":"Safeguarding","high":"Reports are thoroughly investigated to the extent necessary and in a timely manner.","medium":"Reports are investigated, but there is a backlog of reports to investigate and not enough qualified staf f to conduct the investigation.","emerging":"There isn't a reporting system to investigate or reports are dismissed without being investigated."},{"key":"safe_6","area":"Code of conduct","high":"The organization has a code of conduct for its employees, volunteers, and partners that protects all staff from any kind of harassment or discrimination.","medium":"The organization has a CoC, but only for employees.","emerging":"The organization doesn't have a CoC."},{"key":"safe_7","area":"Code of conduct","high":"The organization has a confidential reporting mechanism for code of conduct violations and are they investigated.","medium":"Not an option for this question.","emerging":"There is not a confidential reporting system."},{"key":"safe_8","area":"Code of conduct","high":"The organization has procedures for fraud and theft prevention, mitigation, reporting and investigation. Employees are made aware of the practices, consequences, and how to use the anonymous reporting mechanism for suspected fraud. It's investigated in a timely manner.","medium":"There are procedures for suspected fraud and theft, however, they may not follow best practices in fraud investigation and recovery.","emerging":"No procedures for fraud or theft."},{"key":"safe_9","area":"Code of conduct","high":"The organization trains its staff, interns, and volunteers in the code of conduct. In-person or self-led trainings and workshops occur at regular intervals for staff.","medium":"Staff and affiliates are provided with the code of conduct upon hiring, but there are no required trainings for staff.","emerging":"There is no CoC OR the CoC is outdated and not distributed/available to staff."},{"key":"safe_10","area":"GEDI","high":"The organization demonstrates a commitment gender equality, diversity, and inclusion in its policies, programming, and/or as part of its organizational mission/vision (e.g. is gender equality reflected in the org’s personnel policies and/or is there a separate gender equality policy), as appropriate for the organization's scope and size.","medium":"GEDI is limited to personnel/HR policies but there is no demonstration of them in reality or in programming.","emerging":"Policies are extremely limited or non existent."},{"key":"safe_11","area":"GEDI","high":"The organization have equitable representation of staff of diverse backgrounds at managerial and leadership levels.","medium":"Representation exists through out the organization but isn't equitable (e.g. client groups are not represented among organization's decision makers).","emerging":"No evidence of GEDI at the leadership level."},{"key":"safe_12","area":"GEDI","high":"The organization trains staff in applying gender equality, diversity, and inclusion to their work.","medium":"Trainings are limited to program staff OR HR staff and do not include all staff.","emerging":"No staff training in GEDI."},{"key":"safe_13","area":"Staff health and wellbeing (duty of care)","high":"Staff are given a healthcare benefit – either by insurance or a government plan.","medium":"Not an option for this question.","emerging":"No - it isn't available to staff either by the employer or the government."},{"key":"safe_14","area":"Staff health and wellbeing (duty of care)","high":"Staff have access to counseling services – government subsidized or as an organization/insurance benefit. Staff are encouraged to utilize such services after work-related traumatic events.","medium":"Services exist through the healthcare service, but staff aren't regularly encouraged to access them. No separate staff counseling service.","emerging":"There is little to no duty of care for staff."},{"key":"safe_15","area":"Staff health and wellbeing (duty of care)","high":"Regular morale boosting activities exist for all staff, not only to specific departments (e.g. retreats, staff parties, team building activities).","medium":"Retreats and morale boosting activities are only available for certain departments, not accessible to all.","emerging":"There are no staff retreats or support activities."},{"key":"safe_16","area":"Staff health and wellbeing (duty of care)","high":"Staff are provided with testing kits or support for highly transmissible infectious diseases (e.g.. COVID-19 and malaria).","medium":"Not an option for this question.","emerging":"Testing supplies are not readily available nor is it available through their healthcare services."},{"key":"safe_17","area":"Staff health and wellbeing (duty of care)","high":"Staff are provided with adequate paid sick leave in case of highly transmissible infectious diseases.","medium":"Not an option for this question.","emerging":"Staff are not provided with paid sick leave and/or are discouraged from taking leave when sick."},{"key":"safe_18","area":"Staff health and wellbeing (duty of care)","high":"Emergency medical transportation is available to staff in case of work-related accidents - either through a national ambulance system, one that is covered by the insurance policy or the organization has its own emergency medical transport service.","medium":"There is emergency medical transport, but its coverage is ad hoc and inconcsistent.","emerging":"There is no emergency medical transportation available."},{"key":"safe_19","area":"Security","high":"The organization has a safety and security policy and/or context-appropriate security management plans.","medium":"The security policy exists, however in a limited scope.","emerging":"The organinization does not have a safety and security policy."},{"key":"safe_20","area":"Security","high":"The organization has a mechanism to monitor and analyze changes to the context that may affect security and/or impact humanitarian access.","medium":"There are elements of monitoring in place, but they are not formalized in a SOP.","emerging":"There is no security monitoring system in place."},{"key":"safe_21","area":"Security","high":"The organization has a functional critical incident management system – e.g. staff know their roles in a crisis and the communication mechanism. It is written and available to all staff.","medium":"They have an incident management system, but it is out of date or unavailable to staff.","emerging":"There is no critical incident management system. Critical incidents are handled in a reactive way."},{"key":"safe_22","area":"Security","high":"The organizaiton have a security focal point, and the person is knowledgeable in security in the area.","medium":"Not a designated security expert, but someone with another function (e.g. an HR staff person) is responsible to activate a security plan in case of emergency.","emerging":"There is no organizational security focal point."}]},{"key":"quality","title":"Program quality and strategy","materials":"Materials to review before the meeting:\n1. Strategic plan \n2. Other relevant PQ documents as voluntarily provided","interview":"Please ask the following questions. As the partner answers, ask follow up questions as they arise through the natural flow of conversation. Use active listening skills to create a conversation about the content area.\n\n1. Does your organization have an updated strategic and fundraising plan? \n\n2. How does your organization connect with national and international associations with similar areas of techincal expertise (e.g. attends conferences, workshops, lectures, pays for employee membership to associations)?\n\n3. How does your organization ensure program quality is maintained?\n\n4. How does your organization ensure humanitarian access by providers and clients?\n\n5. Share your experience on challenges the organization faces in accessing communities, and them accessing your services. How has your organization mitigated the impact? \n\n6. Please include challenges and how you overcame them. \n\n7. Tell me about your organization's referral system.\n\nAfter the meeting, use the minutes to answer the questions below.","items":[{"key":"quality_1","area":"Stakeholder analysis","high":"The organization conducts a stakeholder analysis as part of program design.","medium":"Stakeholder analysis is conducted, however older data may be used to access issues or organizational overwhelm.","emerging":"Stakholder analysis isn't conducted, or it is but data isn't disaggregated."},{"key":"quality_2","area":"Strategy","high":"The organization has a current strategic plan.","medium":"The organization has an outdated strategic plan.","emerging":"There is no strategic plan"},{"key":"quality_3","area":"Design based on assessment","high":"Assessment findings are incorporated into program design.","medium":"Yes, however outdated data may have been used when access has been an issue.","emerging":"Assessments are eithe not completed or they do utilize the date for program design."},{"key":"quality_4","area":"Workplan","high":"The organization develops a workplan for each project, updated as project plans change.","medium":"Workplans exist but aren't regularly updated OR workplans exist, are updated but do not include GEDI.","emerging":"Workplans are done only as required by donors, are rarely updated and do not have specific GEDI actions."},{"key":"quality_5","area":"Community","high":"There is trust between the organization and communities it serves. Communities provide feedback to the organization on its services and the organization honors that feedback.","medium":"For the most part, however some communities may have been accidentally overlooked.","emerging":"Little trust between the organization and the communities. Evidence is shown through limited feedback, discrimination in services provided, etc."},{"key":"quality_6","area":"Feedback","high":"They have active and functional client feedback mechanisms.","medium":"Client feedback mechanisms exist, but feedback isn't reviewed at regular intervals.","emerging":"There is no client feedback mechanism."},{"key":"quality_7","area":"Feedback","high":"The client feedback mechanism is documented in a Standard Operating Procedure.","medium":"Client feedback mechanism monitoring exists as part of an employees job description but not a SOP OR it is done regularly but it isn't in a SOP.","emerging":"There is no client feedback mechanism."},{"key":"quality_8","area":"Data disaggregation","high":"The data is disaggregated by sex, age, disability, etc. as relevant in the context.","medium":"Yes, however outdated data may have been used when access has been an issue. But the knowledge and tools exist.","emerging":"Data is not disaggregated."},{"key":"quality_9","area":"Standards","high":"There is a document with the organization’s service delivery standards.","medium":"Yes, but it isn't regularly updated.","emerging":"There is no document of the organization's service delivery standards."},{"key":"quality_10","area":"Standards","high":"Service providers are trained in the standards/given opportunities for continuing education. New staff are trained soon after being hired and all services provides are trained/informed of any changes as soon as they're made. Service providers are provided (organization pays) with the opportunity to attend external trainings and continuing education courses.","medium":"Service providers only attend trainings at the donor's request/requirement OR service providers participate in continuing education, but pay for it themselves.","emerging":"There is no opportunity for service providers to participate in continuing education."},{"key":"quality_11","area":"Referrals","high":"There is a current referral system for services such as emergency medical or mental health care.","medium":"Referral system exsists but is outdated as a result of changing context or staff overwhelm.","emerging":"No referral system"},{"key":"quality_12","area":"Referrals","high":"The referral system has updated information on referral sites.","medium":"Referral site is updated, but updates are delayed.","emerging":"Please put N/A if there is no system. Put 1 if the site has never been updated."},{"key":"quality_13","area":"Past performance","high":"The organization has a demonstrated track record of successfully implementing projects.","medium":"The organization has a moderate performance record implementing projects.","emerging":"The organization has not implemented projects previously."},{"key":"quality_14","area":"Associations and working groups","high":"The organization regularly participates in national associations and/or working groups that are relevant to its areas of expertise.","medium":"The organization occasionally participates in national associations and working groups, but not with consistency.","emerging":"The organization has little or no participation."},{"key":"quality_15","area":"Training","high":"The organization sends its employees to complete trainings and certificate programs.","medium":"Only as required for a specific project.","emerging":"No, however it could be as a result of resource issues."},{"key":"quality_16","area":"Fundraising strategy","high":"There is an updated fundarising strategy.","medium":"There is an outdated fundarising strategy.","emerging":"There is no fundraising strategy."},{"key":"quality_17","area":"Disruption","high":"The organization has a plan for coping with service disruptions.","medium":"The organization has a plan, although it hasn't been updated.","emerging":"There is no plan. Service disruptions are coped with through an ad hoc manner."}]},{"key":"meal","title":"Monitoring, evaluation and learning","materials":"Materials to review before the meeting:\n1. MEAL plan or SOP if documented","interview":"Please ask the following questions. As the partner answers, ask follow up questions as they arise through the natural flow of conversation. Use active listening skills to create a conversation about the content area.\n\n1. How does your organization monitor, evaluate and learn from its programming?\n\n2. Does your organization have a separate team of MEAL experts or is MEAL conducted by the program teams?\n\n3. Or if RHS knows the organization has a MEAL strategy and system, request the following:\n\n4. Please explain your MEAL strategy and process to me. \n\n5. Tell me how you respond to the client's needs based on M&E data.\n\nAfter the meeting, answer the questions below utilizing the minutes.","items":[{"key":"meal_1","area":"MEAL system","high":"The organization has a MEAL sytem that is incorporated across all technical areas.","medium":"Only for certain projects, not the entier organization.","emerging":"There is not MEAL system."},{"key":"meal_2","area":"MEAL system","high":"MEAL system includes output/outcome indicators.","medium":"Output/outcome indicators are used sometimes","emerging":"There are no output/outcome indicators."},{"key":"meal_3","area":"MEAL system","high":"There are comprehensive data collection tools adaptable to all technical areas..","medium":"Data collection tools exist but are under utlized or inefficient.","emerging":"No tools exist."},{"key":"meal_4","area":"MEAL system","high":"Quality check procedures are in place.","medium":"Quality check procedures exist but are used inconsistently.","emerging":"If there are no tools, N/A is the appropriate score. If there are no quality check check procedures, then 1 is appropriate."},{"key":"meal_5","area":"Data","high":"Data is collected at regular intervals.","medium":"Data is collected on an ad hoc/reactive basis.","emerging":"Data is not collected."},{"key":"meal_6","area":"GEDI","high":"Gender, diversity, and inclusion are considerations in the organization's M&E.","medium":"Organization takes facets of gender, diversity, and inclusion into consideration however it could be strengthened.","emerging":"Gender, diversity, and inclusion are not part of the MEAL system."},{"key":"meal_7","area":"Staffing","high":"The organization has a designated department (at least two employees) for MEAL.","medium":"MEAL is conducted by program/technical teams.","emerging":"Organization doesn't have specific staff conducting MEAL."},{"key":"meal_8","area":"Learning","high":"The organization clearly incorporates learning from MEAL by adapting its programming and project design. Organization holds lessons-learned workshops and utilizes that information appropriately.","medium":"There are some gaps in the approach to monitoring.","emerging":"Unclear or no approach to monitoring practices."}]},{"key":"grants","title":"Grant management","materials":"","interview":"Please ask the following questions. As the partner answers, ask follow up questions as they arise through the natural flow of conversation. Use active listening skills to create a conversation about the content area.\n\n1. What processes and routines do you use to review and manage award performance, including budget management, report writing, key decision making and course correction during the life of a project? \n\n2. How is donor compliance ensured?\n\n3. Who are your donors and that is the average value of each grant? Ask to review their grant tracking tool if they have one.\n\n4. How do you prioritize competing deadlines from different donors and projects?\n\nAfter the meeting, please use the minutes to answer the questions below.","items":[{"key":"grants_1","area":"Staff","high":"There are grant management staff, or staff who perform relevant functions (e.g. read and follow the agreements) who are separate from the technical experts/implementers or finance.","medium":"Grant management falls under the remit of technical staff or finance.","emerging":"Evidence of assigned grant mangaement does not exist."},{"key":"grants_2","area":"Tracking","high":"The organization has a clear tracking tool (e.g. an excel sheet, calendar, etc.) that is regularly updated. Anyone can learn the current status of the grant by reviewing the tool: start/end date, reporting deadlines, budget, donor information, etc.","medium":"There is a grant tracking tool, but it is missing key information OR there is a grant tracking tool but it isn't regularly updated.","emerging":"There is not grant tracking tool. Grants management appears to be institutional knowledge."},{"key":"grants_3","area":"Reporting","high":"Organization most submits project and finance reports on time, with the rare late report. However when reports are late, they inform the donor in advance of anticipated delays.","medium":"Most reports are submitted on time. Whenever there is a delay or issue, they rarely inform the donor.","emerging":"Reports are regularly late. Little to no correspondence with the donor about delays."},{"key":"grants_4","area":"Filing","high":"There is a clearly labeled and consistent electronic and paper filing system (as required by donor or preferred by the organization) comprised of all key information required to successfully manage the grants. For example, there is a folder for each grant with proposals, agreements, modifications, programmatic reports and financial reports.","medium":"Filing system is regularly updated, however there is inconsistency between paper and e-files OR the filing system is clear, however files are not regularly updated/maintained.","emerging":"There is no clear and/or consistent filing system."},{"key":"grants_5","area":"Grant meetings","high":"Grant opening meetings and grant check-in/status meetings are held on a regular basis with relevant team members. Minutes are taken at each meeting.Relevant updates on grants (e.g. BVA or program progress information) are sent out over email.","medium":"Grant opening and grant management meetings occur, but not in a timely or consistent manner.","emerging":"There are no regular grant management meetings."},{"key":"grants_6","area":"Communication","high":"Project expenditures vs. budget is clearly communicated from finance to the grant and project teams. The grant and project teams use that information to revise budgets and request budget realignments from donors.","medium":"Grant and/or project managers communicate about expenditures, however it isn't don't on a monthly basis OR it is done regularly, but no action is taken as a result of the information from the meetings with Finance.","emerging":"There are no regular meetings or ways that information is shared about the expenditures vs. the budget."}]},{"key":"finance","title":"Accounting, financial systems and cash management","materials":"Materials to request and review prior to the meeting:\n1. Financial policies and procedures\n2. Signatory policy\n3. Bank account signatory information","interview":"Please ask the following questions. As the partner answers, ask follow up questions as they arise through the natural flow of conversation. Use active listening skills to create a conversation about the content area.\n\n1. Does your organization have sufficient finance and accounting staff?\n\n2. What accounting system is in place - handwritten, excel or a financial software? Who has access and how are staff trained in it?\n\n3. What is the payment process - from the payment request to booking the expense?\n\n4. Tell me the monthly closing and reconciliation process.\n\n5. How does your organization track donor budgets, expenditures and forecast funding needs?\n\n6. Choose 10 to 15 random transactions, preferably for different donors and a range of values, to review. Review to ensure that the organization follows its own financial policies.\n\nAfter the meeting, use the minutes and the supporting documentation to answer the questions below.","items":[{"key":"finance_1","area":"Manual or standard operating procedure","high":"The organizaion has an updated finance manal or SOP that clearly outlines all financial procedures.","medium":"The organization has a finance manual or SOP that may be outdated or may lack some critical steps and controls.","emerging":"Organization relies on institutional memory (e.g. a few peole know all the procedures), but it isn't written down OR finances are totally ad hoc."},{"key":"finance_2","area":"Practice","high":"The practice mirrors the manual or SOP. There are are zero to a a few small discrpencies that are of no concern.","medium":"There are some discrepancies between the process outlined during the meeting demonstrated by the supporting transactions.","emerging":"There is no manual or the practices differ dramatically from the manual."},{"key":"finance_3","area":"Sub offices","high":"There is oversight of the sub-offices by the Finance Manager at the main office.","medium":"There is financial oversight, however it is often done remotely with no in-person meetings or monitoring visits.","emerging":"There is little to no financial oversight."},{"key":"finance_4","area":"Expense allocation","high":"Each project is assigned a project code and expenses are appropriately allocated by donor and project.","medium":"The organization does but reclasses are done frequently.","emerging":"Expenses are not allocated to each project."},{"key":"finance_5","area":"Timesheets","high":"The organization use timesheets where staff can specify time worked on each project. Timesheets are used correctly, include the dates worked and the hours or days charged to each project.","medium":"Timesheets are used, however the time may not be correctly allocated by project or may only serve as a sign-in/sign-out sheet.","emerging":"No time sheets or time sheet system."},{"key":"finance_6","area":"Tracking","high":"There is a clear tracking system where budgets are tracked by project and in accordance to donor line-item flexibility regulations.","medium":"Budgets are tracked by project, however the tracking system is updated less frequently than a monthly basis.","emerging":"There is no infrastructure for the organization to track multiple budgets by project."},{"key":"finance_7","area":"Controls","high":"The expense supporting documentation demonstrate internal controls in the financial processes.","medium":"There are internal controls in practice, but they are not written OR they have written internal controls but aren't always practiced.","emerging":"No demonstrated internal controls and little capacity for internal controls due to staffing shortages OR the capacity exists, but there are no internal controls."},{"key":"finance_8","area":"Exchange rates","high":"The organization has policies in place for currency conversion and exchange rate fluctuation, and manages exchange rate flucations.","medium":"Organization uses bank rate or Oanda on the day of the transfer but does not have a policy nor a way to manage exchange rate gains and losses.","emerging":"Organization has never received foreign currency and has no experience in currency conversion and exchange rate issues."},{"key":"finance_9","area":"Segregation of duties","high":"There is a segregation of duties among staff for reviewing and approving payments and financial reports.","medium":"This answer is not an option.","emerging":"Limited or no segregation of duties among finance staff: e.g. person who requests the payment approves the payment."},{"key":"finance_10","area":"Fraud or theft","high":"Ethical procedures are clearly outlined for fraud or theft investigation.","medium":"This answer is not an option.","emerging":"There are no clearly outlined procedures to handle fraud or theft."},{"key":"finance_11","area":"Bank signatories","high":"There are clearly stated signatories on the bank accounts and bank signatories are in line with their financial policies.","medium":"This answer is not an option.","emerging":"Signatories named in policies and procedures are different than those on the actual bank account."},{"key":"finance_12","area":"Bank reconciliations","high":"There are internal controls for signatories who have financial approval authority. Bank reconciliations are conducted at the same time every month.","medium":"Bank reconciliations are conducted every other month or quarterly.","emerging":"Bank reconciliations are sporadically or never condcuted."},{"key":"finance_13","area":"Cash count","high":"Cash counts are condcuted weekly.","medium":"Cash counts are conducted bi-weekly or monthly.","emerging":"Cash counts are sporadically or never conducted."},{"key":"finance_14","area":"Planning","high":"There is a coordinated effort between program and finance staff to plan project funding needs on a quarterly basis.","medium":"There is a coordinated effort to plan funding needs but planning is on a monthly basis OR planning is done quarterly but with minimal input from program teams.","emerging":"Planning is ad hoc and/or is solely the responsibility of finance with no programmatic input."},{"key":"finance_15","area":"Petty cash","high":"Petty cash is maintained and they follow the petty cash policies.","medium":"If there is no petty cash, input N/A.","emerging":"If there is no petty cash, input N/A."},{"key":"finance_16","area":"Petty cash","high":"There is a safe with controls for petty cash. Only one person has access to petty cash, receipts are required to be provided after expenditures. Petty cash count is conducted by someone different than the person who has access.","medium":"N/A","emerging":"There is petty cash but no safe or secure controls over it."},{"key":"finance_17","area":"Petty cash","high":"Petty cash counts are done weekly.","medium":"Bi-weekly","emerging":"Not at all"}]},{"key":"hr","title":"Personnel and payroll","materials":"Materials to review/request prior to the meeting:\n1. HR policies\n2. Blank timesheet template","interview":"Please ask the following questions. As the partner answers, ask follow up questions as they arise through the natural flow of conversation. Use active listening skills to create a conversation about the content area.\n\n1. Are there designated HR staff? \n\n2. What is the rate of staff turnover? \n\n3. Tell me the process of hiring, performance review, and terminating employment. \n\n4. Tell me how you ensure gender equality, diversity and inclusion in hiring, pay, and promotions. \n\n5. What incentives are there for staff retention?\n\n6. How does your organization ensure that it complies with national labor laws? \n\nAfter the meeting, use the minutes and the supporting documentation to answer the questions below.","items":[{"key":"hr_1","area":"Policies","high":"There are written HR policies that are widely available and accessible to all staff.","medium":"There are policies but they do not accurately reflect the operational situation at the organization OR there are policies but they are not comprehensive.","emerging":"There are no written policies."},{"key":"hr_2","area":"Policies","high":"Employees are informed of those policies and procedures when they are hired. They receive trainings on the policies as needed.","medium":"N/A","emerging":"Employees are not informed of the policies or policy updates."},{"key":"hr_3","area":"Staffing","high":"There are HR staff who are responsible for compliance with the HR policies and national labor law.","medium":"A member of the operations team, usually finance or the office manage, understands the basics of national labor law and acts as the HR person.","emerging":"There are no HR professionals or other trained staff to enforce the policies or ensure compliance with national law."},{"key":"hr_4","area":"Performance","high":"There are appropriate corrective and disciplinary measures for performance issues and HR policy violations, in-line with local labor laws.","medium":"Corrective and disciplinary issues are not appropriate for the issues identified (too extreme or they do not address the issue).","emerging":"There are no corrective measures."},{"key":"hr_5","area":"Termination","high":"Termination procedures are in line with local labor laws. (This needs to be verified by an RHS HR Officer).","medium":"N/A","emerging":"No. This needs to be verified by an RHS HR Officer."},{"key":"hr_6","area":"Pay scale","high":"There is a documented and transparent pay scale.","medium":"There is a documented pay scale but it is not readily available to all staff.","emerging":"Pay scale is done on an ad hoc, donor driven basis or there is no written pay scale."},{"key":"hr_7","area":"GEDI","high":"The organization's HR policies promote gender equality, diversity, and inclusion.","medium":"Policies may only address facets of the GEDI spectrum of inclusion, but are not totally inclusive.","emerging":"There are no inclusion policies."}]},{"key":"supply","title":"Procurement and asset management (supply chain)","materials":"Materials to be requested and reviewed:\n1. Procurement policies and procedures\n2. Inventory and asset management policies\n3. Warehouse management policies\n4. Medical procurement and medical supply chain policies as applicable","interview":"Please ask the following questions. As the partner answers, ask follow up questions as they arise through the natural flow of conversation. Use active listening skills to create a conversation about the content area.\n\n1. Are there designated procurement staff?\n\n2. What are the procurement thresholds?\n\n3. Tell me the process for each threshold.\n\n4. Tell me how inventory and assets are managed.\n\n5. If your organization has a warehouse, could you please tell me about your warehousing protocols? \n\n6. If the partner will use its own vehicle or a project vehicle as part of the partnership, ask the following: Please tell me about your vehicle usage, records, and maintencance policies.\n\n7. If the partners is procuring medical commodities: Please tell me about your medical supply chain management process, including quality control and appropriate tracking, storage, and distribution techniques.\n\n7. Ask to select 5 to 7 samples of documentation that demonstrates they follow their procurement policies from procurement planning to the tender process to their inventory management.\n\nAfter the meeting, use the minutes to answer the remaining questions below.","items":[{"key":"supply_1","area":"Policies","high":"Procurement policies and procedures are clearly documented and outlined and follow best practices.","medium":"Policies are documented but there is some room for improvement or clarity.","emerging":"Minimal or no procurement policies."},{"key":"supply_2","area":"Planning","high":"The organization maintains a current procurement plan.","medium":"They have a procurement plan, but it is updated occasionally.","emerging":"No procurement plan."},{"key":"supply_3","area":"Tracking","high":"All purchase requests are tracked from start to completion using either a database or specialized procurement software.","medium":"There is a tracking system but it is not updated regularly OR there is a tracking system, it's updated at each step, however it may not include all required information.","emerging":"There is no tracking system."},{"key":"supply_4","area":"Checks","high":"All purchase requests are checked for completeness when received (description, price, codes, etc.).","medium":"N/A","emerging":"Purchase requests are not checked for completeness when received."},{"key":"supply_5","area":"Staffing","high":"There is a procurement department separate from other departments and the size of the team is appropriate for the amount being procured annually.","medium":"There may be a designated person in Finance or another department who is responsible for procurement and understands procurement. However there isn't a teach of procurement staff proportionate to the amount being procured annually.","emerging":"Procurement is done on an ad hoc basis between program and finance staff."},{"key":"supply_6","area":"Authorisation","high":"There is an authorization matrix that demonstrates which staff can approve which level of procurements.","medium":"There is a document however it has not been updated.","emerging":"There is no written authorization matrix."},{"key":"supply_7","area":"Thresholds","high":"There is a written threshold that the organization follows to determine when to obtain quotes vs. an RFP/tender as demonstrated by the supporting documents provided.","medium":"There is a threshold matrix, but it isn't always followed.","emerging":"There is no written threshold matrix."},{"key":"supply_8","area":"Tenders","high":"There is a documented procedure for the RFP/tender process. Supporting documents demonstrate that each step is followed in the process.","medium":"There is a documented procedure, however it is not thorough.","emerging":"There is no documented procedure."},{"key":"supply_9","area":"Tenders","high":"A committee of staff from different departments review the quotes/proposals.","medium":"There is a committee, however it does not have broad respresentation from programs and finance.","emerging":"There is no committee."},{"key":"supply_10","area":"Supporting documents","high":"Supporting documentation for vendor payment is consistent with finance policies.","medium":"This answer is not an option.","emerging":"Supporting documentation is inconsistent or non-existent."},{"key":"supply_11","area":"Filing","high":"There are procurement files that are up to date, systematic and readily accessible.","medium":"There is a filing system, but it is not up to date.","emerging":"There is no systematic filing system."},{"key":"supply_12","area":"Suppliers","high":"There is a preferred vendors/suppliers list that is updated regularly.","medium":"Preferred vendors/supppliers list exists, but is out of date.","emerging":"There is no preferred supliers list"},{"key":"supply_13","area":"Due diligence","high":"There is a written due diligence process used before contracts are signed with vendors.","medium":"There is a process, but some enhancements may be necessary.","emerging":"There is no vendor due diligence process."},{"key":"supply_14","area":"Performance","high":"The vendor's performance reviewed against the contract.","medium":"A process exists, but isn't used consistently.","emerging":"There is no performance review process."},{"key":"supply_15","area":"Receiving","high":"Receiving reports & inventory records are used to substantiate the receipt of commodities and supplies.","medium":"There is a receiving system, but it's not used in every delivery.","emerging":"There is no clearly outlined receiving system."},{"key":"supply_16","area":"Receiving","high":"The partner verifies quality and quantity for every delivery.","medium":"There is a process, however goods and materials are not always verified.","emerging":"There is no verification method in place."},{"key":"supply_17","area":"Vehicle log","high":"The partner maintains a vehicle logbook that clearly tracks mileage, kept up to date with each trip.","medium":"There is a log book and it's usually updated, but sometimes the driver and/or rider forget to update it.","emerging":"There is no log book or one exists, but is never used."},{"key":"supply_18","area":"Vehicle log","high":"The vehicle log records project codes and signatures for each trip.","medium":"Project codes and signtatures are included in the log book at least half the time.","emerging":"Project codes and signatures are rarely recorded in the log book."},{"key":"supply_19","area":"Pharmaceuticals (where relevant)","high":"There is a thorough pre-qualification process for all pharmaceutical suppliers.","medium":"This answer is not an option.","emerging":"No pre-qualification process exists."},{"key":"supply_20","area":"Pharmaceuticals and food (where relevant0","high":"Batch numbers and expiration-dates are recorded for perishable goods such as pharmaceuticals and food.","medium":"This answer is not an option.","emerging":"The organization does not track batch numbers."},{"key":"supply_21","area":"Pharmaceuticals and food (where relevant0","high":"Quality control is performed on the received pharmaceuticals/food for every batch of received goods and materials.","medium":"There is a system for quality control, but it is not used consistently.","emerging":"There is no system for quality control"},{"key":"supply_22","area":"Warehouse (RHS should tour)","high":"The organization maintains a warehouse that is appropriately secured for the context.","medium":"The organization has a warehouse, but has minimal security.","emerging":"No, the organization should have a warehouse given the amount of commodities kept on hand, but does not."},{"key":"supply_23","area":"Warehouse","high":"There is a prominently displayed/readily available SOP for warehousing protocols.","medium":"There are protocols but they are not readily available.","emerging":"There are no warehousing procedures or the procedures are in a language not understood by the warehouse staff."},{"key":"supply_24","area":"Warehouse","high":"The organization uses LIFO, FIFO, or best by for distribution as appropriate to the specific commodities and materials.","medium":"This answer is not an option.","emerging":"No discernable method is used."},{"key":"supply_25","area":"Warehouse","high":"The organization uses inventory and bin cards and they are up to date.","medium":"They are used but are not regularly updated.","emerging":"No, inventoy and bin cards are not used."},{"key":"supply_26","area":"Loss","high":"There is a process for recording and investigating inventory loss as required.","medium":"There is a process for loss, but it may not be current OR there is a consistent process used to record and investigate loss but it may not be written. However the loss is documented.","emerging":"There is no written process for inventory loss."},{"key":"supply_27","area":"Inventory counts","high":"Inventory counts are conducted bi-weekly","medium":"Monthly to quarterly","emerging":"Once or twice per year or never."},{"key":"supply_28","area":"Inventory","high":"Inventories are correctly recorded in the financial system.","medium":"They have the capacity to record inventories in the financial system, but it isn't always correct or done regularly.","emerging":"Inventories are not recorded in the financial system."},{"key":"supply_29","area":"Tagging","high":"Fixed assets (e.g. computers, printers) are physically tagged and the tagging and tracking system is capable of identifying the grant they were purchased under (source of funds).","medium":"This answer is not an option.","emerging":"No- it is difficult to determine which fixed assets were purchased with what funding source."}]},{"key":"subaward","title":"Sub-award management","materials":"Materials to request and review prior to the meeting:\n1. Subaward Management policies and tools as applicable.","interview":"Please ask the following questions. As the partner answers, ask follow up questions as they arise through the natural flow of conversation. Use active listening skills to create a conversation about the content area.\n\nPlease tell me about your organization's partnership/subaward process from partner selection to close out. Please include, if possible, information on due diligence, capacity assessment, agreement templates, and monitoring.\n\nAfter the meeting, utilize the minutes to answer the questions below.","items":[{"key":"subaward_1","area":"ATC checks","high":"ATC checks are conducted on all subaward recipients.","medium":"N/A","emerging":"ATC checks are not conducted on subaward recipients."},{"key":"subaward_2","area":"Capacity analysis","high":"The organization conducts capacity assessments on subaward recipients in accordance with the organizations policy (e.g. if the organization's policy is to provide the partner with a self-assessment, that counts).","medium":"Capacity assessments are not done consistently OR they are done consistently but the tool gains minimal information.","emerging":"No capacity assessments are conducted."},{"key":"subaward_3","area":"Agreements","high":"The organization has donor-informed templates for subaward agreements and modifications","medium":"There are some agreement and modification templates, but they are not donor informed.","emerging":"No agreement or modification templates."},{"key":"subaward_4","area":"Monitoring","high":"Subaward recipients are consistently monitored with a frequency per the organization's policy.","medium":"Monitoring is conducted on an ad hoc basis/inconsistently, but is done.","emerging":"There is no subaward monitoring."}]}]

/** Risk Analysis → category labels in the "PCA outcomes" table, in workbook order */
export const PCA_CATEGORY_LABELS: Record<PcaKey, string> = {"safe":"Safe programming","quality":"Program quality","meal":"MEAL","grants":"Grant Management","finance":"Accounting, finance and cash management","hr":"Personnel and payroll","supply":"Procurement and asset management (supply chain)","subaward":"Sub-award management"}

export const DD_RISK_GROUPS: { key: 'vetting' | 'contextual' | 'rhs'; title: string; desc: string }[] = [{"key":"vetting","title":"Risks identified in vetting and capacity analysis","desc":"Material risks identified in the vetting and capacity analysis process"},{"key":"contextual","title":"Contextual risks","desc":"Material risks that stem from the context that we are partnering in, such as: \nactive conflict, economic insecurity, political unrest, climate crisis/natural disasters or infectious diseases"},{"key":"rhs","title":"Risks associated with RHS identity or capacity","desc":"Consider any issues associated with the RHS's capacity to perform its role in the partnership. Consider, for example: technical engagement, funding, supply chain, and donor requirements"}]

