export const RISK_MATRIX: Record<string, 'Low' | 'Medium' | 'High' | 'Very High'> = {"10":"Low","11":"Low","12":"Low","13":"Low","14":"Medium","15":"Medium","20":"Low","21":"Low","22":"Medium","23":"Medium","24":"Medium","25":"Medium","30":"Low","31":"Low","32":"Medium","33":"High","34":"High","35":"High","40":"Medium","41":"Medium","42":"Medium","43":"High","44":"High","45":"Very High","50":"Medium","51":"Medium","52":"Medium","53":"High","54":"Very High","55":"Very High","00":"Low","01":"Low","02":"Low","03":"Low","04":"Medium","05":"Medium"}
